package com.mamtrex.hospital.insurance;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/insurance-claims") public class InsuranceClaimController { private final InsuranceClaimRepository repo; private final AuditService audit; public InsuranceClaimController(InsuranceClaimRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String payer, @jakarta.validation.constraints.NotBlank String policyNumber, @jakarta.validation.constraints.NotBlank String claimNumber, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public InsuranceClaim create(@Valid @RequestBody Request r){var e=repo.save(new InsuranceClaim(r.patientId(), r.payer(), r.policyNumber(), r.claimNumber(), r.status()));audit.record("CREATE","InsuranceClaim",e.getId().toString(),"created");return e;} @GetMapping public List<InsuranceClaim> list(){return repo.findAll();} @GetMapping("/{id}") public InsuranceClaim get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("InsuranceClaim not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("InsuranceClaim not found: "+id);repo.deleteById(id);audit.record("DELETE","InsuranceClaim",id.toString(),"deleted");} }
